import{_ as o,c as a,o as l,aM as t}from"./chunks/framework.kKeYZnSg.js";const c="/fe-handbook/assets/v2-2748a0dbe09fad1b21998c2e64621962_r.BLHlRDng.jpg",g=JSON.parse('{"title":"CNAME","description":"","frontmatter":{},"headers":[],"relativePath":"fundamentals/network/cname.md","filePath":"fundamentals/network/cname.md","lastUpdated":1785481197000}'),r={name:"fundamentals/network/cname.md"};function n(s,e,i,d,m,p){return l(),a("div",null,e[0]||(e[0]=[t('<h1 id="cname" tabindex="-1">CNAME <a class="header-anchor" href="#cname" aria-label="Permalink to &quot;CNAME&quot;">​</a></h1><blockquote><p>A记录是将域名解析成IP，CNAME是将域名解析成另外一个域名。</p></blockquote><p><img src="'+c+'" alt="img"></p><hr><h2 id="_1-主要用途" tabindex="-1"><strong>1. 主要用途</strong> <a class="header-anchor" href="#_1-主要用途" aria-label="Permalink to &quot;**1. 主要用途**&quot;">​</a></h2><ul><li><strong>域名别名</strong>：将一个子域名（如 <code>www.example.com</code>）指向另一个域名（如 <code>example.com</code> 或第三方服务域名）。</li><li><strong>CDN 或云服务集成</strong>：例如，将 <code>assets.yoursite.com</code> 指向 <code>your-cdn-provider.com</code>。</li><li><strong>简化管理</strong>：当目标域名 IP 变更时，只需修改目标域名的 A 记录，所有 CNAME 记录会自动生效。</li></ul><hr><h2 id="_2-工作原理" tabindex="-1"><strong>2. 工作原理</strong> <a class="header-anchor" href="#_2-工作原理" aria-label="Permalink to &quot;**2. 工作原理**&quot;">​</a></h2><ul><li><strong>示例</strong>： 假设你的网站主域名是 <code>example.com</code>，而你想让 <code>www.example.com</code> 也指向同一个网站。 可以设置一条 CNAME 记录：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>www.example.com.  CNAME  example.com.</span></span></code></pre></div><p>当用户访问 <code>www.example.com</code> 时，DNS 会先解析 <code>example.com</code> 的 IP 地址，再返回给用户。</p><ul><li><strong>注意</strong>：</li><li>CNAME 只能指向<strong>另一个域名</strong>，不能直接指向 IP 地址（需用 A 或 AAAA 记录）。 <ul><li>CNAME 不能与其他记录类型（如 MX、TXT）共存于同一子域名。</li></ul></li></ul><hr><h2 id="_3-常见应用场景" tabindex="-1"><strong>3. 常见应用场景</strong> <a class="header-anchor" href="#_3-常见应用场景" aria-label="Permalink to &quot;**3. 常见应用场景**&quot;">​</a></h2><ol><li><strong>网站主域名与子域名</strong><ul><li><code>www.example.com</code> → <code>example.com</code></li><li><code>blog.example.com</code> → <code>第三方博客平台（如 Medium）</code></li></ul></li><li><strong>CDN 或云存储</strong><ul><li><code>static.example.com</code> → <code>xyz.cloudfront.net</code>（AWS CDN）</li><li><code>images.example.com</code> → <code>storage.googleapis.com</code>（Google Cloud）</li></ul></li><li><strong>第三方服务集成</strong><ul><li><code>mail.example.com</code> → <code>mailprovider.com</code>（企业邮箱服务）</li><li><code>shop.example.com</code> → <code>shopify.com</code>（电商平台）</li></ul></li></ol><hr><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h2><ul><li><a href="https://blog.csdn.net/DD_orz/article/details/100034049" target="_blank" rel="nofollow noopener noreferrer">https://blog.csdn.net/DD_orz/article/details/100034049</a></li></ul>',18)]))}const h=o(r,[["render",n]]);export{g as __pageData,h as default};
